import { z } from "zod";
import { ProgressProfileSchema } from "@cas/education-core";

export const SETTINGS_SCHEMA_VERSION = 2;

export const ReduceMotionPreferenceSchema = z.enum(["system", "reduce", "no-preference"]);
export type ReduceMotionPreference = z.infer<typeof ReduceMotionPreferenceSchema>;

export const ThemePreferenceSchema = z.enum(["system", "light", "dark"]);
export type ThemePreference = z.infer<typeof ThemePreferenceSchema>;

export const AppSettingsSchema = z.object({
  schemaVersion: z.literal(SETTINGS_SCHEMA_VERSION),
  theme: ThemePreferenceSchema.default("system"),
  reduceMotion: ReduceMotionPreferenceSchema,
  autoRotate: z.boolean(),
  liveTutorEnabled: z.boolean(),
  liveTutorConsent: z.boolean(),
  updatedAt: z.string().min(10),
});
export type AppSettings = z.infer<typeof AppSettingsSchema>;

export const StoredStateSchema = z.object({
  profile: ProgressProfileSchema,
  settings: AppSettingsSchema,
});
export type StoredState = z.infer<typeof StoredStateSchema>;

export { ProgressProfileSchema };

export const ExportBundleSchema = z.object({
  app: z.literal("cell-architecture-studio"),
  exportVersion: z.literal(2),
  exportedAt: z.string().min(10),
  profile: ProgressProfileSchema,
  settings: AppSettingsSchema,
});
export type ExportBundle = z.infer<typeof ExportBundleSchema>;

export function createDefaultSettings(now: string): AppSettings {
  return {
    schemaVersion: SETTINGS_SCHEMA_VERSION,
    theme: "system",
    reduceMotion: "system",
    autoRotate: false,
    liveTutorEnabled: false,
    liveTutorConsent: false,
    updatedAt: now,
  };
}
