import {
  QuizAnswerRecordSchema,
  createEmptyProfile,
  type ProgressProfile,
} from "@cas/education-core";
import {
  AppSettingsSchema,
  ExportBundleSchema,
  ProgressProfileSchema,
  type AppSettings,
  type ExportBundle,
  type StoredState,
  createDefaultSettings,
} from "./schema";

export const DB_NAME = "cell-architecture-studio";
export const DB_VERSION = 2;
const PROFILE_KEY = "local";
const SETTINGS_KEY = "local";

export type PersistenceErrorCode = "unavailable" | "blocked" | "quota" | "corrupt" | "unknown";

export class PersistenceError extends Error {
  readonly code: PersistenceErrorCode;
  constructor(code: PersistenceErrorCode, message: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = "PersistenceError";
    this.code = code;
  }
}

export type LoadedState = StoredState & {
  kind: "indexeddb" | "memory";
  /** True when stored data was unreadable and defaults were substituted. */
  recovered: boolean;
};

export type PersistenceAdapter = {
  kind: "indexeddb" | "memory";
  load: () => Promise<LoadedState>;
  saveProfile: (profile: ProgressProfile) => Promise<void>;
  saveSettings: (settings: AppSettings) => Promise<void>;
  exportAll: () => Promise<ExportBundle>;
  deleteAll: () => Promise<void>;
  close: () => void;
};

function nowIso(): string {
  return new Date().toISOString();
}

function emptyState(now: string): StoredState {
  return {
    profile: createEmptyProfile(now),
    settings: createDefaultSettings(now),
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function stringOr(value: unknown, fallback: string): string {
  return typeof value === "string" && value.length >= 10 ? value : fallback;
}

/**
 * Reads the v1 profile shape, which predated the `profileId`/answer records.
 * Unknown or malformed fields are dropped rather than trusted.
 */
export function migrateStoredProfile(value: unknown, now: string): ProgressProfile | null {
  const current = ProgressProfileSchema.safeParse(value);
  if (current.success) return current.data;
  if (!isRecord(value)) return null;
  const schemaVersion = typeof value.schemaVersion === "number" ? value.schemaVersion : 1;
  if (schemaVersion !== 1) return null;

  const viewedSource = value.viewedStructures ?? value.viewed;
  const viewedStructures: Record<string, string[]> = {};
  if (isRecord(viewedSource)) {
    for (const [key, entries] of Object.entries(viewedSource)) {
      if (Array.isArray(entries)) {
        viewedStructures[key] = entries.filter(
          (entry): entry is string => typeof entry === "string",
        );
      }
    }
  }

  const answers: Record<string, unknown> = {};
  if (isRecord(value.answers)) {
    for (const [key, entry] of Object.entries(value.answers)) {
      if (!isRecord(entry)) continue;
      const record = QuizAnswerRecordSchema.safeParse({
        specimenId: entry.specimenId,
        structureId: entry.structureId,
        correct: entry.correct,
        answeredAt: stringOr(entry.answeredAt, now),
      });
      if (record.success) answers[key] = record.data;
    }
  }

  const candidate = {
    schemaVersion: 2 as const,
    profileId: "local" as const,
    createdAt: stringOr(value.createdAt, now),
    updatedAt: stringOr(value.updatedAt, now),
    viewedStructures,
    answers,
    favorites: Array.isArray(value.favorites)
      ? value.favorites.filter((entry): entry is string => typeof entry === "string")
      : [],
    lastVisited: isRecord(value.lastVisited)
      ? Object.fromEntries(
          Object.entries(value.lastVisited).filter(
            (entry): entry is [string, string] => typeof entry[1] === "string",
          ),
        )
      : {},
  };
  const migrated = ProgressProfileSchema.safeParse(candidate);
  return migrated.success ? migrated.data : null;
}

export function migrateStoredSettings(value: unknown, now: string): AppSettings | null {
  const current = AppSettingsSchema.safeParse(value);
  if (current.success) return current.data;
  if (!isRecord(value)) return null;
  const schemaVersion = typeof value.schemaVersion === "number" ? value.schemaVersion : 1;
  if (schemaVersion !== 1) return null;
  const migrated = AppSettingsSchema.safeParse({
    schemaVersion: 2,
    theme: value.theme === "light" || value.theme === "dark" ? value.theme : "system",
    reduceMotion:
      value.reduceMotion === true
        ? "reduce"
        : value.reduceMotion === false
          ? "no-preference"
          : value.reduceMotion === "reduce" || value.reduceMotion === "no-preference"
            ? value.reduceMotion
            : "system",
    autoRotate: value.autoRotate === true,
    liveTutorEnabled: value.liveTutorEnabled === true,
    liveTutorConsent: value.liveTutorConsent === true,
    updatedAt: stringOr(value.updatedAt, now),
  });
  return migrated.success ? migrated.data : null;
}

function requestToPromise<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () =>
      reject(
        new PersistenceError("unknown", request.error?.message ?? "IndexedDB request failed", {
          cause: request.error,
        }),
      );
  });
}

function transactionDone(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () =>
      reject(
        new PersistenceError(
          "unknown",
          transaction.error?.message ?? "IndexedDB transaction failed",
          {
            cause: transaction.error,
          },
        ),
      );
    transaction.onabort = () =>
      reject(
        new PersistenceError(
          transaction.error?.name === "QuotaExceededError" ? "quota" : "unknown",
          transaction.error?.message ?? "IndexedDB transaction was aborted",
          { cause: transaction.error },
        ),
      );
  });
}

/**
 * Opens (and migrates) the local database. Version 1 used one "state" object
 * store; version 2 splits progress and settings. Migration copies any v1 record
 * into the new stores inside the upgrade transaction, so no learner data is
 * silently discarded.
 */
export function openDatabase(factory: IDBFactory = indexedDB): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    let request: IDBOpenDBRequest;
    try {
      request = factory.open(DB_NAME, DB_VERSION);
    } catch (cause) {
      reject(new PersistenceError("unavailable", "IndexedDB could not be opened", { cause }));
      return;
    }

    request.onupgradeneeded = (event) => {
      const db = request.result;
      const transaction = request.transaction;
      if (!transaction) return;

      if (!db.objectStoreNames.contains("progress")) {
        db.createObjectStore("progress", { keyPath: "profileId" });
      }
      if (!db.objectStoreNames.contains("settings")) {
        db.createObjectStore("settings");
      }

      const oldVersion = event.oldVersion;
      if (oldVersion > 0 && oldVersion < 2 && db.objectStoreNames.contains("state")) {
        const legacy = transaction.objectStore("state");
        const cursorRequest = legacy.openCursor();
        cursorRequest.onsuccess = () => {
          const cursor = cursorRequest.result;
          if (!cursor) {
            if (db.objectStoreNames.contains("state")) db.deleteObjectStore("state");
            return;
          }
          const value = cursor.value as { profile?: unknown; settings?: unknown };
          const profile = migrateStoredProfile(value.profile, nowIso());
          if (profile) {
            transaction.objectStore("progress").put(profile);
          }
          const settings = migrateStoredSettings(value.settings, nowIso());
          if (settings) {
            transaction.objectStore("settings").put(settings, SETTINGS_KEY);
          }
          cursor.continue();
        };
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => {
      const error = request.error;
      const code: PersistenceErrorCode =
        error?.name === "VersionError" || error?.name === "InvalidStateError"
          ? "blocked"
          : "unknown";
      reject(
        new PersistenceError(code, error?.message ?? "IndexedDB failed to open", { cause: error }),
      );
    };
    request.onblocked = () =>
      reject(
        new PersistenceError(
          "blocked",
          "Another tab is holding an older database version open. Close other tabs and retry.",
        ),
      );
  });
}

export type IndexedDbAdapterOptions = {
  factory?: IDBFactory;
  now?: () => string;
};

export function createIndexedDbAdapter(options: IndexedDbAdapterOptions = {}): PersistenceAdapter {
  const factory = options.factory ?? (typeof indexedDB !== "undefined" ? indexedDB : undefined);
  if (!factory) {
    throw new PersistenceError("unavailable", "IndexedDB is not available in this browser");
  }
  const now = options.now ?? nowIso;
  let databasePromise: Promise<IDBDatabase> | null = null;

  const db = () => {
    databasePromise ??= openDatabase(factory).catch((cause: unknown) => {
      databasePromise = null;
      throw cause;
    });
    return databasePromise;
  };

  const read = async (): Promise<StoredState & { recovered: boolean }> => {
    const database = await db();
    const transaction = database.transaction(["progress", "settings"], "readonly");
    const profileRequest = transaction.objectStore("progress").get(PROFILE_KEY);
    const settingsRequest = transaction.objectStore("settings").get(SETTINGS_KEY);
    const [rawProfile, rawSettings] = await Promise.all([
      requestToPromise(profileRequest),
      requestToPromise(settingsRequest),
    ]);
    await transactionDone(transaction);

    const defaults = emptyState(now());
    const migratedProfile = migrateStoredProfile(rawProfile, defaults.profile.createdAt);
    const migratedSettings = migrateStoredSettings(rawSettings, defaults.settings.updatedAt);
    return {
      profile: migratedProfile ?? defaults.profile,
      settings: migratedSettings ?? defaults.settings,
      recovered:
        (rawProfile !== undefined && migratedProfile === null) ||
        (rawSettings !== undefined && migratedSettings === null),
    };
  };

  return {
    kind: "indexeddb",
    async load() {
      try {
        const state = await read();
        return { ...state, kind: "indexeddb" };
      } catch (cause) {
        if (cause instanceof PersistenceError) throw cause;
        throw new PersistenceError("unknown", "Local progress could not be read", { cause });
      }
    },
    async saveProfile(profile) {
      const database = await db();
      const transaction = database.transaction("progress", "readwrite");
      transaction.objectStore("progress").put(profile);
      await transactionDone(transaction);
    },
    async saveSettings(settings) {
      const database = await db();
      const transaction = database.transaction("settings", "readwrite");
      transaction.objectStore("settings").put(settings, SETTINGS_KEY);
      await transactionDone(transaction);
    },
    async exportAll() {
      const state = await read();
      return ExportBundleSchema.parse({
        app: "cell-architecture-studio",
        exportVersion: 2,
        exportedAt: now(),
        profile: state.profile,
        settings: state.settings,
      });
    },
    async deleteAll() {
      const database = await db();
      const transaction = database.transaction(["progress", "settings"], "readwrite");
      transaction.objectStore("progress").clear();
      transaction.objectStore("settings").clear();
      await transactionDone(transaction);
    },
    close() {
      void databasePromise?.then((database) => database.close()).catch(() => undefined);
      databasePromise = null;
    },
  };
}

export function createMemoryAdapter(
  options: { now?: () => string; initial?: StoredState } = {},
): PersistenceAdapter & { peek: () => StoredState } {
  const now = options.now ?? nowIso;
  let state = options.initial ?? emptyState(now());
  const kind = "memory" as const;
  return {
    kind,
    async load() {
      return { ...state, kind, recovered: false };
    },
    async saveProfile(profile) {
      state = { ...state, profile };
    },
    async saveSettings(settings) {
      state = { ...state, settings };
    },
    async exportAll() {
      return ExportBundleSchema.parse({
        app: "cell-architecture-studio",
        exportVersion: 2,
        exportedAt: now(),
        profile: state.profile,
        settings: state.settings,
      });
    },
    async deleteAll() {
      state = emptyState(now());
    },
    close() {
      // Nothing to release.
    },
    peek: () => state,
  };
}

/** Uses IndexedDB when present and falls back to an in-memory profile. */
export function resolvePersistenceAdapter(
  options: IndexedDbAdapterOptions = {},
): PersistenceAdapter {
  try {
    return createIndexedDbAdapter(options);
  } catch {
    return createMemoryAdapter({ now: options.now });
  }
}

export async function requestPersistentStorage(
  storage: StorageManager | undefined = typeof navigator !== "undefined"
    ? navigator.storage
    : undefined,
): Promise<boolean> {
  if (!storage?.persist) return false;
  try {
    if (storage.persisted && (await storage.persisted())) return true;
    return await storage.persist();
  } catch {
    return false;
  }
}
