import { createStore, type StoreApi } from "zustand/vanilla";
import {
  createEmptyProfile,
  recordQuizAnswer,
  recordStructureView,
  summarizeProgress,
  toggleFavorite,
  type ProgressProfile,
} from "@cas/education-core";
import {
  createDefaultSettings,
  type AppSettings,
  type ReduceMotionPreference,
  type ThemePreference,
} from "@cas/persistence";
import { REGISTRY_SPECIMENS } from "../content";
import { routeFromPath, type RouteId } from "../routes";

export type LabSimulationId = "bilayer" | "action-potential";

export type AppState = {
  route: RouteId;
  labSimulation: LabSimulationId;
  specimenId: string;
  compareLeftId: string;
  compareRightId: string;
  selectedStructureId: string | null;
  profile: ProgressProfile;
  settings: AppSettings;
  hydrated: boolean;
  persistenceKind: "indexeddb" | "memory" | "error" | "pending";
  notice: string;

  setRoute: (route: RouteId) => void;
  setLabSimulation: (simulation: LabSimulationId) => void;
  selectSpecimen: (specimenId: string) => void;
  selectCompare: (side: "left" | "right", specimenId: string) => void;
  swapCompare: () => void;
  selectStructure: (structureId: string | null) => void;
  hydrate: (input: {
    profile: ProgressProfile;
    settings: AppSettings;
    persistenceKind: "indexeddb" | "memory" | "error";
  }) => void;
  setTheme: (preference: ThemePreference) => void;
  setReduceMotion: (preference: ReduceMotionPreference) => void;
  setAutoRotate: (enabled: boolean) => void;
  setLiveTutor: (input: { enabled: boolean; consent: boolean }) => void;
  markStructureViewed: (specimenId: string, structureId: string) => void;
  answerQuestion: (input: {
    specimenId: string;
    structureId: string;
    questionId: string;
    correct: boolean;
  }) => void;
  toggleFavorite: (specimenId: string, structureId: string) => void;
  resetProgress: () => void;
  notify: (message: string) => void;
};

export type AppStore = StoreApi<AppState>;

function defaultSpecimenId(): string {
  return REGISTRY_SPECIMENS[0]?.id ?? "plant-cell";
}

export function createAppStore(): AppStore {
  const now = new Date().toISOString();
  return createStore<AppState>()((set, get) => ({
    route: typeof window !== "undefined" ? routeFromPath(window.location.pathname) : "explore",
    labSimulation: "bilayer",
    specimenId: defaultSpecimenId(),
    compareLeftId: defaultSpecimenId(),
    compareRightId:
      REGISTRY_SPECIMENS.find((specimen) => specimen.id === "animal-cell")?.id ?? "animal-cell",
    selectedStructureId: null,
    profile: createEmptyProfile(now),
    settings: createDefaultSettings(now),
    hydrated: false,
    persistenceKind: "pending",
    notice: "",

    setRoute: (route) => {
      if (get().route === route) return;
      set({ route });
    },
    setLabSimulation: (labSimulation) => {
      if (get().labSimulation === labSimulation) return;
      set({ labSimulation });
    },
    selectSpecimen: (specimenId) => {
      const exists = REGISTRY_SPECIMENS.some((specimen) => specimen.id === specimenId);
      if (!exists) return;
      set({
        specimenId,
        selectedStructureId: null,
      });
    },
    selectCompare: (side, specimenId) => {
      const exists = REGISTRY_SPECIMENS.some((specimen) => specimen.id === specimenId);
      if (!exists) return;
      if (side === "left") set({ compareLeftId: specimenId });
      else set({ compareRightId: specimenId });
    },
    swapCompare: () => {
      const { compareLeftId, compareRightId } = get();
      set({ compareLeftId: compareRightId, compareRightId: compareLeftId });
    },
    selectStructure: (structureId) => {
      if (get().selectedStructureId === structureId) return;
      set({ selectedStructureId: structureId });
    },
    hydrate: ({ profile, settings, persistenceKind }) => {
      set({
        profile,
        settings,
        persistenceKind,
        hydrated: true,
        route:
          typeof window !== "undefined" ? routeFromPath(window.location.pathname) : get().route,
      });
    },
    setTheme: (preference) => {
      if (get().settings.theme === preference) return;
      set({
        settings: {
          ...get().settings,
          theme: preference,
          updatedAt: new Date().toISOString(),
        },
      });
    },
    setReduceMotion: (preference) => {
      set({
        settings: {
          ...get().settings,
          reduceMotion: preference,
          updatedAt: new Date().toISOString(),
        },
      });
    },
    setAutoRotate: (enabled) => {
      set({
        settings: { ...get().settings, autoRotate: enabled, updatedAt: new Date().toISOString() },
      });
    },
    setLiveTutor: ({ enabled, consent }) => {
      set({
        settings: {
          ...get().settings,
          liveTutorEnabled: enabled,
          liveTutorConsent: enabled ? consent : false,
          updatedAt: new Date().toISOString(),
        },
        notice: enabled
          ? "Live tutoring is enabled for this browser. Questions you submit are sent to the configured provider."
          : "Live tutoring is off. The offline cited study helper remains available.",
      });
    },
    markStructureViewed: (specimenId, structureId) => {
      const update = recordStructureView(
        get().profile,
        specimenId,
        structureId,
        new Date().toISOString(),
      );
      if (update.changed) set({ profile: update.profile });
    },
    answerQuestion: ({ specimenId, structureId, questionId, correct }) => {
      const update = recordQuizAnswer(get().profile, {
        specimenId,
        structureId,
        questionId,
        correct,
        now: new Date().toISOString(),
      });
      if (update.changed) set({ profile: update.profile });
    },
    toggleFavorite: (specimenId, structureId) => {
      const update = toggleFavorite(
        get().profile,
        specimenId,
        structureId,
        new Date().toISOString(),
      );
      set({
        profile: update.profile,
        notice: update.profile.favorites.includes(`${specimenId}:${structureId}`)
          ? "Saved to favourites."
          : "Removed from favourites.",
      });
    },
    resetProgress: () => {
      set({
        profile: createEmptyProfile(new Date().toISOString()),
        notice: "Local progress was reset.",
      });
    },
    notify: (message) => set({ notice: message }),
  }));
}

export const appStore = createAppStore();

export function masteryForSpecimen(store: AppStore, specimenId: string): number {
  const specimen = REGISTRY_SPECIMENS.find((candidate) => candidate.id === specimenId);
  if (!specimen) return 0;
  return summarizeProgress(store.getState().profile, specimenId, specimen.structures.length)
    .mastery;
}
