import { useState } from "react";
import type { Specimen, Structure } from "@cas/content-registry";
import { getSource } from "../content";
import { navigateToLab } from "../lib/navigation";
import { IconArrowUpRight, IconBilayer, IconBolt, IconStar } from "./Icons";

export function StructureInspector({
  specimen,
  selected,
  onSelect,
  isFavorite,
  onToggleFavorite,
}: {
  specimen: Specimen;
  selected: Structure | null;
  onSelect: (structureId: string | null) => void;
  isFavorite: boolean;
  onToggleFavorite: () => void;
}) {
  return (
    <div className="inspector" aria-labelledby="structure-list-heading">
      <div className="inspector__list">
        <div className="inspector__list-header">
          <h2 id="structure-list-heading">Structures</h2>
          <span className="pill">{specimen.structures.length}</span>
        </div>
        <p className="muted small">
          Select a structure to focus the mesh and read its cited facts. Every structure below is
          mapped to authored geometry.
        </p>
        <ul>
          {specimen.structures.map((structure, index) => {
            const active = structure.id === selected?.id;
            return (
              <li key={structure.id}>
                <button
                  type="button"
                  className={`structure-button${active ? " structure-button--active" : ""}`}
                  aria-pressed={active}
                  onClick={() => onSelect(active ? null : structure.id)}
                >
                  <span className="structure-button__index">
                    {String(index + 1).padStart(2, "0")}
                  </span>
                  <span className="structure-button__name">{structure.name}</span>
                  <span className="structure-button__mapping" title="Geometry mapped">
                    <span className="structure-button__dot" aria-hidden="true" />
                    <span className="visually-hidden">Geometry mapped.</span>
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
        <p className="muted small">
          Mapping confidence is shown in the detail panel. Colour is schematic, not a biological
          measurement.
        </p>
      </div>

      <article className="inspector__detail" aria-live="polite">
        {selected ? (
          <div key={`${specimen.id}:${selected.id}`} className="inspector__detail-enter">
            <StructureDetail
              specimen={specimen}
              structure={selected}
              isFavorite={isFavorite}
              onToggleFavorite={onToggleFavorite}
              onClear={() => onSelect(null)}
            />
          </div>
        ) : (
          <div className="empty-state">
            <p className="eyebrow">Nothing selected</p>
            <h2>Start with a structure</h2>
            <p>
              Pick one from the list, or select a highlighted mesh in the 3D view. Facts, source
              locators, and mapping evidence appear here.
            </p>
            <p className="muted small">
              Tip: the canvas is never the only route. The list is fully keyboard operable and
              contains the same information.
            </p>
          </div>
        )}
      </article>
    </div>
  );
}

function StructureDetail({
  specimen,
  structure,
  isFavorite,
  onToggleFavorite,
  onClear,
}: {
  specimen: Specimen;
  structure: Structure;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onClear: () => void;
}) {
  return (
    <>
      <div className="inspector__detail-head">
        <div>
          <p className="eyebrow">
            {specimen.name} · {structure.mapping.confidence} confidence mapping
          </p>
          <h2>{structure.name}</h2>
        </div>
        <div className="inspector__detail-actions">
          <button
            type="button"
            className="button button--ghost"
            aria-pressed={isFavorite}
            onClick={onToggleFavorite}
          >
            <IconStar filled={isFavorite} />
            <span>{isFavorite ? "Saved" : "Save"}</span>
          </button>
          <button type="button" className="button button--ghost" onClick={onClear}>
            Close
          </button>
        </div>
      </div>

      <p className="lede">{structure.summary}</p>

      <section aria-labelledby="function-heading">
        <h3 id="function-heading">What it does</h3>
        <p>{structure.function}</p>
      </section>

      {(structure.id === "plasma-membrane" || structure.id === "outer-membrane") && (
        <div className="inspector__lab-cta">
          <div className="inspector__lab-cta-copy">
            <IconBilayer size={24} />
            <div>
              <p className="eyebrow">Interactive simulation</p>
              <p className="small">
                Explore how phospholipids self-assemble into a bilayer in the interactive Lab.
              </p>
            </div>
          </div>
          <button
            type="button"
            className="button button--primary"
            onClick={() => navigateToLab("bilayer")}
          >
            Open bilayer lab
          </button>
        </div>
      )}

      {specimen.id === "neuron" &&
        (structure.id === "axon" ||
          structure.id === "myelin-sheath" ||
          structure.id === "axon-terminal" ||
          structure.id === "soma") && (
          <div className="inspector__lab-cta">
            <div className="inspector__lab-cta-copy">
              <IconBolt size={22} />
              <div>
                <p className="eyebrow">Interactive simulation</p>
                <p className="small">
                  Watch how Na⁺ and K⁺ voltage-gated channels drive an action potential along the
                  axon.
                </p>
              </div>
            </div>
            <button
              type="button"
              className="button button--primary"
              onClick={() => navigateToLab("action-potential")}
            >
              Open action potential lab
            </button>
          </div>
        )}

      <section aria-labelledby="facts-heading">
        <h3 id="facts-heading">Reviewed facts</h3>
        <ul className="facts">
          {structure.facts.map((fact) => {
            const source = getSource(fact.sourceId);
            const secondReviewed =
              fact.secondReview?.status === "approved" && Boolean(fact.secondReview.reviewedAt);
            return (
              <li key={fact.id} className="fact">
                <p>{fact.statement}</p>
                <p className="fact__cite">
                  {fact.highImpact && !secondReviewed && (
                    <span className="pill pill--warn">Second review needed</span>
                  )}
                  {fact.highImpact && secondReviewed && (
                    <span className="pill">Second review recorded</span>
                  )}
                  <a href={source?.url ?? "#sources"} target="_blank" rel="noreferrer noopener">
                    <span>
                      {source?.publisher ?? "Source"} · {fact.locator}
                    </span>
                    <IconArrowUpRight />
                  </a>
                </p>
              </li>
            );
          })}
        </ul>
      </section>

      <CorrectionReport
        key={`${specimen.id}:${structure.id}`}
        specimen={specimen}
        structure={structure}
      />

      <section aria-labelledby="mapping-heading" className="mapping">
        <h3 id="mapping-heading">How the schematic maps</h3>
        <p className="muted">
          <strong>Evidence:</strong> {structure.mapping.evidence}
        </p>
        <p className="muted">
          <strong>Mesh parts:</strong>{" "}
          {structure.mapping.meshNames.length > 0 ? structure.mapping.meshNames.join(", ") : "none"}
        </p>
        <p className="muted small">{structure.mapping.note}</p>
        {structure.schematicNote && <p className="callout">{structure.schematicNote}</p>}
      </section>

      <p className="muted small">
        Biology review status: <strong>{specimen.contentReview.status}</strong>. Content version{" "}
        {specimen.contentVersion}. High-impact claims require a recorded second review before
        release.
      </p>
    </>
  );
}

function CorrectionReport({ specimen, structure }: { specimen: Specimen; structure: Structure }) {
  const [copyState, setCopyState] = useState<"idle" | "copied" | "failed">("idle");
  const fieldId = `correction-${specimen.id}-${structure.id}`;
  const report = [
    "Correction report — Cell Architecture Studio",
    `Specimen: ${specimen.name} (${specimen.id}) · content ${specimen.contentVersion}`,
    `Structure: ${structure.name} (${structure.id})`,
    `Page: ${window.location.href}`,
    "",
    "Claims in scope:",
    ...structure.facts.map(
      (fact) => `- ${fact.id}: ${fact.statement} [${fact.sourceId} · ${fact.locator}]`,
    ),
    "",
    "What is wrong:",
    "",
    "Suggested correction and source:",
    "",
  ].join("\n");

  async function copyReport() {
    try {
      if (!navigator.clipboard) throw new Error("Clipboard is unavailable");
      await navigator.clipboard.writeText(report);
      setCopyState("copied");
    } catch {
      setCopyState("failed");
    }
  }

  return (
    <details className="correction">
      <summary>Report a correction</summary>
      <p className="muted small">
        Nothing is sent automatically and none of your progress is included. Copy this report and
        send it to the project maintainer or issue tracker. It contains registry identifiers, the
        cited claims, and the current page URL.
      </p>
      <label className="visually-hidden" htmlFor={fieldId}>
        Correction report
      </label>
      <textarea id={fieldId} className="correction__report" readOnly rows={7} value={report} />
      <div className="correction__actions">
        <button type="button" className="button button--ghost" onClick={() => void copyReport()}>
          Copy report
        </button>
        <span className="muted small" role="status">
          {copyState === "copied" && "Copied to clipboard."}
          {copyState === "failed" && "Copy failed. Select the text and copy it manually."}
        </span>
      </div>
    </details>
  );
}
