/**
 * Analytical damped-harmonic spring solver & fluid gesture primitives modeled
 * after Apple's "Designing Fluid Interfaces" (WWDC 2018).
 */

export type SpringConfig = {
  /** 1.0 = critically damped (no overshoot); < 1.0 = under-damped bounce. */
  dampingRatio: number;
  /** Tightness factor in seconds (lower = snappier, not a fixed duration). */
  response: number;
};

export const SPRING_UI: SpringConfig = { dampingRatio: 1.0, response: 0.34 };
export const SPRING_MOMENTUM: SpringConfig = { dampingRatio: 0.82, response: 0.36 };
export const SPRING_SNAPPY: SpringConfig = { dampingRatio: 1.0, response: 0.24 };

export type SpringState = {
  value: number;
  velocity: number;
  settled: boolean;
};

/** Apple's exponential momentum projection from release velocity (px/s). */
export function projectMomentum(velocityPxPerSec: number, decelerationRate = 0.998): number {
  const rate = Math.max(0.5, Math.min(0.9999, decelerationRate));
  return ((velocityPxPerSec / 1000) * rate) / (1 - rate);
}

/** Progressive boundary resistance (never a hard stop). */
export function rubberband(overshoot: number, dimension: number, constant = 0.55): number {
  if (dimension <= 0) return 0;
  return (overshoot * dimension * constant) / (dimension + constant * Math.abs(overshoot));
}

/** Closed-form spring integration step, unconditionally stable for any dt. */
export function stepSpring(
  value: number,
  velocity: number,
  target: number,
  dt: number,
  config: SpringConfig = SPRING_UI,
  precision = 0.05,
): SpringState {
  if (dt <= 0) {
    const settled = Math.abs(value - target) < precision && Math.abs(velocity) < precision * 10;
    return { value: settled ? target : value, velocity: settled ? 0 : velocity, settled };
  }

  const zeta = Math.max(0.05, config.dampingRatio);
  const omega = (2 * Math.PI) / Math.max(0.05, config.response);
  const x0 = value - target;
  const v0 = velocity;

  let nextX: number;
  let nextV: number;

  if (Math.abs(zeta - 1) < 1e-4) {
    const decay = Math.exp(-omega * dt);
    const c2 = v0 + omega * x0;
    nextX = (x0 + c2 * dt) * decay;
    nextV = (v0 - omega * c2 * dt) * decay;
  } else if (zeta < 1) {
    const omegaD = omega * Math.sqrt(1 - zeta * zeta);
    const decay = Math.exp(-zeta * omega * dt);
    const c2 = (v0 + zeta * omega * x0) / omegaD;
    const cos = Math.cos(omegaD * dt);
    const sin = Math.sin(omegaD * dt);
    nextX = decay * (x0 * cos + c2 * sin);
    nextV =
      decay * ((c2 * omegaD - zeta * omega * x0) * cos - (x0 * omegaD + zeta * omega * c2) * sin);
  } else {
    const s = omega * Math.sqrt(zeta * zeta - 1);
    const r1 = -omega * zeta + s;
    const r2 = -omega * zeta - s;
    const c1 = (v0 - r2 * x0) / (2 * s);
    const c2 = x0 - c1;
    const e1 = Math.exp(r1 * dt);
    const e2 = Math.exp(r2 * dt);
    nextX = c1 * e1 + c2 * e2;
    nextV = c1 * r1 * e1 + c2 * r2 * e2;
  }

  const nextValue = target + nextX;
  const settled = Math.abs(nextX) < precision && Math.abs(nextV) < precision * 10;
  return {
    value: settled ? target : nextValue,
    velocity: settled ? 0 : nextV,
    settled,
  };
}

export type SpringController = {
  getValue: () => number;
  getVelocity: () => number;
  setImmediate: (value: number) => void;
  setTarget: (
    target: number,
    options?: {
      config?: SpringConfig;
      velocity?: number;
      reduceMotion?: boolean;
      precision?: number;
    },
  ) => void;
  subscribe: (listener: (value: number, velocity: number, settled: boolean) => void) => () => void;
  stop: () => void;
};

/**
 * Interruptible animated spring value driven via requestAnimationFrame.
 * Retargeting starts seamlessly from the live presentation value & velocity.
 */
export function createSpringValue(initialValue: number): SpringController {
  let value = initialValue;
  let velocity = 0;
  let target = initialValue;
  let activeConfig = SPRING_UI;
  let activePrecision = 0.05;
  let rafId: number | null = null;
  let lastTime = 0;
  const listeners = new Set<(v: number, vel: number, settled: boolean) => void>();

  const notify = (settled: boolean) => {
    for (const listener of listeners) listener(value, velocity, settled);
  };

  const cancelFrame = () => {
    if (rafId !== null && typeof cancelAnimationFrame === "function") {
      cancelAnimationFrame(rafId);
    }
    rafId = null;
  };

  const frame = (now: number) => {
    const dt = lastTime > 0 ? Math.min((now - lastTime) / 1000, 0.064) : 1 / 60;
    lastTime = now;
    const next = stepSpring(value, velocity, target, dt, activeConfig, activePrecision);
    value = next.value;
    velocity = next.velocity;
    notify(next.settled);
    if (next.settled) {
      rafId = null;
      return;
    }
    rafId = requestAnimationFrame(frame);
  };

  return {
    getValue: () => value,
    getVelocity: () => velocity,
    setImmediate: (nextValue: number) => {
      cancelFrame();
      value = nextValue;
      target = nextValue;
      velocity = 0;
      notify(true);
    },
    setTarget: (nextTarget, options = {}) => {
      if (options.velocity !== undefined) velocity = options.velocity;
      if (options.config) activeConfig = options.config;
      if (options.precision !== undefined) activePrecision = options.precision;
      target = nextTarget;

      if (options.reduceMotion || typeof requestAnimationFrame !== "function") {
        cancelFrame();
        value = nextTarget;
        velocity = 0;
        notify(true);
        return;
      }

      if (Math.abs(value - target) < activePrecision && Math.abs(velocity) < activePrecision * 10) {
        cancelFrame();
        value = target;
        velocity = 0;
        notify(true);
        return;
      }

      if (rafId === null) {
        lastTime = typeof performance !== "undefined" ? performance.now() : 0;
        rafId = requestAnimationFrame(frame);
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    stop: () => {
      cancelFrame();
    },
  };
}
