import { useSyncExternalStore } from "react";
import type { StoreApi } from "zustand/vanilla";

/**
 * Subscribes a component to a vanilla Zustand store. The viewer never imports
 * React state: only the host component re-renders on command changes.
 */
export function useVanillaStore<T>(store: StoreApi<T>): T;
export function useVanillaStore<T, U>(store: StoreApi<T>, selector: (state: T) => U): U;
export function useVanillaStore<T, U = T>(store: StoreApi<T>, selector?: (state: T) => U): T | U {
  const select = selector ?? ((state: T) => state as unknown as U);
  return useSyncExternalStore(
    store.subscribe,
    () => select(store.getState()),
    () => select(store.getState()),
  );
}
