import { z } from "zod";

/**
 * Deterministic progression rules. A profile records unique structure views and
 * the latest answer per question, so refreshing or repeating a quiz cannot
 * inflate mastery. All timestamps are injected, which keeps tests stable.
 */
export const PROFILE_SCHEMA_VERSION = 2;

export const QuizAnswerRecordSchema = z.object({
  specimenId: z.string().min(2),
  structureId: z.string().min(2),
  correct: z.boolean(),
  answeredAt: z.string().min(10),
});
export type QuizAnswerRecord = z.infer<typeof QuizAnswerRecordSchema>;

export const ProgressProfileSchema = z.object({
  schemaVersion: z.literal(PROFILE_SCHEMA_VERSION),
  profileId: z.literal("local"),
  createdAt: z.string().min(10),
  updatedAt: z.string().min(10),
  viewedStructures: z.record(z.string(), z.array(z.string())),
  answers: z.record(z.string(), QuizAnswerRecordSchema),
  favorites: z.array(z.string()),
  lastVisited: z.record(z.string(), z.string()),
});
export type ProgressProfile = z.infer<typeof ProgressProfileSchema>;

export type ProgressSummary = {
  specimenId: string;
  structuresViewed: number;
  structuresTotal: number;
  questionsAnswered: number;
  questionsCorrect: number;
  /** 0–100, half exploration and half unique-question accuracy. */
  mastery: number;
  completed: boolean;
};

export type ProfileUpdate = {
  profile: ProgressProfile;
  /** False when the action was a no-op because it had already been recorded. */
  changed: boolean;
};

export function createEmptyProfile(now: string): ProgressProfile {
  return {
    schemaVersion: PROFILE_SCHEMA_VERSION,
    profileId: "local",
    createdAt: now,
    updatedAt: now,
    viewedStructures: {},
    answers: {},
    favorites: [],
    lastVisited: {},
  };
}

export function recordStructureView(
  profile: ProgressProfile,
  specimenId: string,
  structureId: string,
  now: string,
): ProfileUpdate {
  const viewed = profile.viewedStructures[specimenId] ?? [];
  if (viewed.includes(structureId)) {
    return { profile, changed: false };
  }
  return {
    profile: {
      ...profile,
      updatedAt: now,
      viewedStructures: {
        ...profile.viewedStructures,
        [specimenId]: [...viewed, structureId],
      },
      lastVisited: { ...profile.lastVisited, [specimenId]: now },
    },
    changed: true,
  };
}

export function recordQuizAnswer(
  profile: ProgressProfile,
  input: {
    specimenId: string;
    structureId: string;
    questionId: string;
    correct: boolean;
    now: string;
  },
): ProfileUpdate {
  const previous = profile.answers[input.questionId];
  if (previous && previous.correct === input.correct) {
    return { profile, changed: false };
  }
  return {
    profile: {
      ...profile,
      updatedAt: input.now,
      answers: {
        ...profile.answers,
        [input.questionId]: {
          specimenId: input.specimenId,
          structureId: input.structureId,
          correct: input.correct,
          answeredAt: input.now,
        },
      },
      lastVisited: { ...profile.lastVisited, [input.specimenId]: input.now },
    },
    changed: true,
  };
}

export function toggleFavorite(
  profile: ProgressProfile,
  specimenId: string,
  structureId: string,
  now: string,
): ProfileUpdate {
  const key = `${specimenId}:${structureId}`;
  const exists = profile.favorites.includes(key);
  return {
    profile: {
      ...profile,
      updatedAt: now,
      favorites: exists
        ? profile.favorites.filter((favorite) => favorite !== key)
        : [...profile.favorites, key],
    },
    changed: true,
  };
}

export function summarizeProgress(
  profile: ProgressProfile,
  specimenId: string,
  structureCount: number,
): ProgressSummary {
  const viewed = new Set(profile.viewedStructures[specimenId] ?? []);
  const answers = Object.values(profile.answers).filter(
    (answer) => answer.specimenId === specimenId,
  );
  const correct = answers.filter((answer) => answer.correct).length;
  const exploration = structureCount > 0 ? Math.min(1, viewed.size / structureCount) : 0;
  const accuracy = answers.length > 0 ? correct / answers.length : 0;
  const mastery = Math.round((exploration * 0.5 + accuracy * 0.5) * 100);
  return {
    specimenId,
    structuresViewed: Math.min(viewed.size, structureCount),
    structuresTotal: structureCount,
    questionsAnswered: answers.length,
    questionsCorrect: correct,
    mastery,
    completed: structureCount > 0 && viewed.size >= structureCount && answers.length >= 3,
  };
}

export function totalMastery(
  profile: ProgressProfile,
  specimens: Array<{ id: string; structureCount: number }>,
): number {
  if (specimens.length === 0) return 0;
  const sum = specimens.reduce(
    (total, specimen) =>
      total + summarizeProgress(profile, specimen.id, specimen.structureCount).mastery,
    0,
  );
  return Math.round(sum / specimens.length);
}

export function isFavorite(
  profile: ProgressProfile,
  specimenId: string,
  structureId: string,
): boolean {
  return profile.favorites.includes(`${specimenId}:${structureId}`);
}
