import { memo, type CSSProperties } from "react";
import { summarizeProgress, type ProgressProfile } from "@cas/education-core";
import type { Specimen } from "@cas/content-registry";
import { previewUrl } from "../content";

export const SpecimenRail = memo(function SpecimenRail({
  specimens,
  activeId,
  onSelect,
  profile,
}: {
  specimens: Specimen[];
  activeId: string;
  onSelect: (specimenId: string) => void;
  profile: ProgressProfile;
}) {
  return (
    <aside className="rail" aria-labelledby="rail-heading">
      <div className="rail__header">
        <div className="rail__header-top">
          <p className="eyebrow">Gallery</p>
          <span className="pill">{specimens.length}</span>
        </div>
        <h2 id="rail-heading">Twelve specimens, one scale-free studio</h2>
      </div>
      <div className="rail__scroll">
        <ul className="rail__list">
          {specimens.map((specimen) => {
            const active = specimen.id === activeId;
            const summary = summarizeProgress(profile, specimen.id, specimen.structures.length);
            return (
              <li key={specimen.id}>
                <button
                  type="button"
                  className={`specimen-card${active ? " specimen-card--active" : ""}`}
                  style={{ "--card-accent": specimen.accent } as CSSProperties}
                  aria-current={active ? "true" : undefined}
                  onClick={() => onSelect(specimen.id)}
                >
                  <img
                    src={previewUrl(specimen.previewPath)}
                    alt=""
                    width={88}
                    height={88}
                    decoding="async"
                  />
                  <span className="specimen-card__body">
                    <span className="specimen-card__name">{specimen.name}</span>
                    <span className="specimen-card__meta">
                      {specimen.domain} · {specimen.structures.length} structures
                      {specimen.contentReview.status !== "approved" && " · draft"}
                    </span>
                    <span
                      className="specimen-card__progress"
                      role="img"
                      aria-label={`${summary.mastery}% mastery`}
                    >
                      <span style={{ width: `${summary.mastery}%` }} />
                    </span>
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      </div>
    </aside>
  );
});
