/**
 * Runtime base-path resolution so a single build works at "/" or under any
 * nested subpath (e.g. "/cell-architecture/" or "/nested/studio/"), while also
 * honoring an explicit VITE_BASE_PATH build override.
 */
export function normalizeBasePath(base: string): string {
  const trimmed = base.trim();
  if (!trimmed || trimmed === "." || trimmed === "./" || trimmed === "/") return "/";
  const withoutDot = trimmed.replace(/^\.\//, "");
  const collapsed = `/${withoutDot}`.replace(/\/+/g, "/");
  return collapsed.endsWith("/") ? collapsed : `${collapsed}/`;
}

export function detectBasePath(options?: { envBase?: string; moduleUrl?: string }): string {
  const envBase = options?.envBase ?? import.meta.env?.BASE_URL;
  if (typeof envBase === "string" && envBase.startsWith("/")) {
    const normalized = normalizeBasePath(envBase);
    if (normalized !== "/") return normalized;
  }

  const moduleUrl = options?.moduleUrl ?? import.meta.url;
  if (typeof moduleUrl === "string" && /^https?:\/\//i.test(moduleUrl)) {
    try {
      const { pathname } = new URL(moduleUrl);
      const match = pathname.match(/^(.*)\/assets\/[^/]+$/);
      if (match) {
        return normalizeBasePath(`${match[1] ?? ""}/`);
      }
    } catch {
      // Fall back to root if moduleUrl cannot be parsed.
    }
  }

  return "/";
}

export const APP_BASE_PATH = detectBasePath();

const SPECIAL_URL_RE = /^(?:[a-z][a-z0-9+.-]*:|\/\/|#)/i;

export function resolveAppPath(path: string, base: string = APP_BASE_PATH): string {
  if (!path || SPECIAL_URL_RE.test(path)) return path;
  const normalizedBase = normalizeBasePath(base);
  if (normalizedBase !== "/" && path.startsWith(normalizedBase)) return path;
  const clean = path.replace(/^\.?\//, "");
  return `${normalizedBase}${clean}`;
}
