import { isFavorite } from "@cas/education-core";
import {
  assetFor,
  previewUrl,
  REGISTRY_SPECIMENS,
  requireSpecimen,
  TRAIT_LABELS,
} from "../content";
import { appStore } from "../state/app-store";
import { useVanillaStore } from "../lib/use-vanilla-store";
import { effectiveReducedMotion, useSystemReducedMotion } from "../lib/media";
import { SpecimenRail } from "../components/SpecimenRail";
import { StructureInspector } from "../components/StructureInspector";
import { LazyViewerPane } from "../viewer/lazy";
import { Suspense, useCallback } from "react";
import { ViewerBoundary, ViewerLoadFallback, ViewerSkeleton } from "../components/ViewerBoundary";

export function ExplorePage() {
  const specimenId = useVanillaStore(appStore, (s) => s.specimenId);
  const selectedStructureId = useVanillaStore(appStore, (s) => s.selectedStructureId);
  const profile = useVanillaStore(appStore, (s) => s.profile);
  const reduceMotionPref = useVanillaStore(appStore, (s) => s.settings.reduceMotion);
  const autoRotate = useVanillaStore(appStore, (s) => s.settings.autoRotate);
  const systemReduced = useSystemReducedMotion();
  const reduceMotion = effectiveReducedMotion(reduceMotionPref, systemReduced);
  const specimen = requireSpecimen(specimenId);
  const asset = assetFor(specimen);
  const selected =
    specimen.structures.find((structure) => structure.id === selectedStructureId) ?? null;
  const favorite = selected ? isFavorite(profile, specimen.id, selected.id) : false;

  const selectSpecimen = useCallback((nextId: string) => {
    appStore.getState().selectSpecimen(nextId);
  }, []);

  const selectStructure = useCallback(
    (structureId: string | null) => {
      appStore.getState().selectStructure(structureId);
      if (structureId) appStore.getState().markStructureViewed(specimen.id, structureId);
    },
    [specimen.id],
  );

  return (
    <div className="page page--explore">
      <SpecimenRail
        specimens={REGISTRY_SPECIMENS}
        activeId={specimen.id}
        onSelect={selectSpecimen}
        profile={profile}
      />

      <div className="workbench">
        <header className="specimen-header">
          <div className="specimen-header__main">
            <p className="eyebrow">
              {specimen.domain} · {specimen.cellType}
            </p>
            <h1>{specimen.name}</h1>
            <p className="lede specimen-header__summary">{specimen.summary}</p>
          </div>
          <div className="specimen-header__pills">
            <span className="badge badge--draft">
              {specimen.contentReview.status === "approved" ? "Biology reviewed" : "Draft biology"}
            </span>
            <span className="pill">{specimen.sizeNote}</span>
          </div>
        </header>

        <div className="workbench__grid">
          <ViewerBoundary
            fallback={
              <ViewerLoadFallback
                previewPath={previewUrl(specimen.previewPath)}
                name={specimen.name}
                message="The viewer code could not be loaded. Reload, or read the structure facts in the list."
              />
            }
          >
            <Suspense
              fallback={
                <ViewerSkeleton
                  previewPath={previewUrl(specimen.previewPath)}
                  name={specimen.name}
                  detail="Loading only the viewer chunk. Text and sources are already available."
                />
              }
            >
              <LazyViewerPane
                specimen={specimen}
                asset={asset}
                selectedStructureId={selected?.id ?? null}
                onSelectStructure={selectStructure}
                reduceMotion={reduceMotion}
                autoRotate={autoRotate}
              />
            </Suspense>
          </ViewerBoundary>

          <StructureInspector
            specimen={specimen}
            selected={selected}
            onSelect={selectStructure}
            isFavorite={favorite}
            onToggleFavorite={() => {
              if (selected) appStore.getState().toggleFavorite(specimen.id, selected.id);
            }}
          />
        </div>

        <div className="specimen-notes-grid">
          <section className="panel specimen-overview-card" aria-labelledby="overview-heading">
            <p className="eyebrow">Specimen notes</p>
            <h2 id="overview-heading">About this specimen</h2>
            <p>{specimen.overview}</p>
            <p className="muted small">
              <strong>Species:</strong> {specimen.species.replace(/\.$/, "")}. {specimen.taxonNote}
            </p>
            <p className="muted small">{specimen.scaleNote}</p>
          </section>

          <section className="panel traits-inline" aria-labelledby="quick-facts">
            <p className="eyebrow">Profile</p>
            <h2 id="quick-facts">At a glance</h2>
            <dl>
              {specimen.traits.map((trait) => (
                <div key={trait.id}>
                  <dt>{TRAIT_LABELS[trait.id]}</dt>
                  <dd>{trait.value}</dd>
                </div>
              ))}
            </dl>
            <p className="muted small">
              Schematic colour and proportions are diagram conventions, not measurements. The
              registry declares every mesh-to-structure mapping used by highlighting.
            </p>
          </section>
        </div>
      </div>
    </div>
  );
}
