import { APP_BASE_PATH, normalizeBasePath } from "./lib/base-path";

export const ROUTES = [
  { id: "explore", path: "/", label: "Explore", description: "Browse specimens and structures" },
  { id: "compare", path: "/compare", label: "Compare", description: "Put two cells side by side" },
  {
    id: "learn",
    path: "/learn",
    label: "Learn",
    description: "Flashcards, quiz, and cited study help",
  },
  {
    id: "lab",
    path: "/lab",
    label: "Lab",
    description: "Interactive membrane self-assembly lab",
  },
  {
    id: "about",
    path: "/about",
    label: "About",
    description: "Provenance, privacy, and accessibility",
  },
] as const;

export type RouteId = (typeof ROUTES)[number]["id"];

export function relativeRoutePath(pathname: string, base: string = APP_BASE_PATH): string {
  const normalizedBase = normalizeBasePath(base);
  let relative = pathname || "/";
  if (normalizedBase !== "/") {
    const baseWithoutSlash = normalizedBase.slice(0, -1);
    if (relative === baseWithoutSlash || relative === normalizedBase) {
      relative = "/";
    } else if (relative.startsWith(normalizedBase)) {
      relative = `/${relative.slice(normalizedBase.length)}`;
    }
  }
  return relative.replace(/\/+$/, "") || "/";
}

export function routeFromPath(pathname: string, base: string = APP_BASE_PATH): RouteId {
  const normalized = relativeRoutePath(pathname, base);
  if (normalized === "/index.html") return "explore";
  const match = ROUTES.find((route) => route.path === normalized);
  return match?.id ?? "explore";
}

export function isKnownPath(pathname: string, base: string = APP_BASE_PATH): boolean {
  const normalized = relativeRoutePath(pathname, base);
  return ROUTES.some((route) => route.path === normalized);
}

export function pathForRoute(route: RouteId, base: string = APP_BASE_PATH): string {
  const normalizedBase = normalizeBasePath(base);
  const routePath = ROUTES.find((candidate) => candidate.id === route)?.path ?? "/";
  if (routePath === "/") return normalizedBase;
  return `${normalizedBase}${routePath.slice(1)}`;
}

export function routeLabel(route: RouteId): string {
  return ROUTES.find((candidate) => candidate.id === route)?.label ?? "Explore";
}
