import { useEffect, useState } from "react";
import type { ReduceMotionPreference, ThemePreference } from "@cas/persistence";

const QUERY = "(prefers-reduced-motion: reduce)";
const LIGHT_SCHEME_QUERY = "(prefers-color-scheme: light)";

export function useSystemReducedMotion(): boolean {
  return useMediaQuery(QUERY);
}

export function effectiveReducedMotion(
  preference: ReduceMotionPreference,
  systemReduced: boolean,
): boolean {
  if (preference === "reduce") return true;
  if (preference === "no-preference") return false;
  return systemReduced;
}

export function useSystemColorScheme(): "light" | "dark" {
  return useMediaQuery(LIGHT_SCHEME_QUERY) ? "light" : "dark";
}

export function effectiveTheme(
  preference: ThemePreference,
  systemScheme: "light" | "dark",
): "light" | "dark" {
  if (preference === "light" || preference === "dark") return preference;
  return systemScheme;
}

export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState(() => {
    if (typeof window === "undefined" || !window.matchMedia) return false;
    return window.matchMedia(query).matches;
  });

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const media = window.matchMedia(query);
    const update = () => setMatches(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, [query]);

  return matches;
}
