import { PROCEDURAL_EVIDENCE, PROCEDURAL_LICENSE, PROCEDURAL_RIGHTS_REVIEW } from "./authoring";
import { sources } from "./citations";
import { animalCellSpecimen } from "./content/animal-cell";
import { bacteriaSpecimen } from "./content/bacteria";
import { epithelialCellSpecimen } from "./content/epithelial-cell";
import { humanBrainCutoutSpecimen } from "./content/human-brain-cutout";
import { humanBrainSpecimen } from "./content/human-brain";
import { muscleCellSpecimen } from "./content/muscle-cell";
import { neuronSpecimen } from "./content/neuron";
import { parameciumSpecimen } from "./content/paramecium";
import { plantCellSpecimen } from "./content/plant-cell";
import { redBloodCellSpecimen } from "./content/red-blood-cell";
import { whiteBloodCellSpecimen } from "./content/white-blood-cell";
import { yeastCellSpecimen } from "./content/yeast-cell";
import type { AssetRecord, Registry, Source, Specimen } from "./schema";
import { TRAIT_LABELS, type CompareTraitId } from "./traits";

export { TRAIT_LABELS, sources };
export type { AssetRecord, CompareTraitId, Registry, Source, Specimen };

export const specimens: Specimen[] = [
  plantCellSpecimen,
  whiteBloodCellSpecimen,
  neuronSpecimen,
  epithelialCellSpecimen,
  bacteriaSpecimen,
  animalCellSpecimen,
  muscleCellSpecimen,
  redBloodCellSpecimen,
  yeastCellSpecimen,
  parameciumSpecimen,
  humanBrainSpecimen,
  humanBrainCutoutSpecimen,
];

function catalogAsset(specimen: Specimen): AssetRecord {
  return {
    id: specimen.assetId,
    kind: "procedural",
    uri: `procedural://${specimen.slug}`,
    byteSize: 0,
    license: PROCEDURAL_LICENSE,
    licenseEvidence: [PROCEDURAL_EVIDENCE],
    rightsReview: PROCEDURAL_RIGHTS_REVIEW,
    attribution: `${PROCEDURAL_LICENSE.attributionText} Specimen: ${specimen.name} (${specimen.species}).`,
    export: { png: true, glb: true },
    capabilities: specimen.capabilities,
  };
}

export const catalogAssets: AssetRecord[] = specimens.map(catalogAsset);

export const catalog: Registry = {
  version: "0.1.0",
  specimens,
  assets: catalogAssets,
  sources,
};

const specimenIndex = new Map(specimens.map((specimen) => [specimen.id, specimen]));
const assetIndex = new Map(catalogAssets.map((asset) => [asset.id, asset]));
const sourceIndex = new Map(sources.map((source) => [source.id, source]));

export function getSpecimen(specimenId: string): Specimen | undefined {
  return specimenIndex.get(specimenId);
}

export function requireSpecimen(specimenId: string): Specimen {
  const specimen = specimenIndex.get(specimenId);
  if (!specimen) throw new Error(`Unknown specimen: ${specimenId}`);
  return specimen;
}

export function getAsset(assetId: string): AssetRecord | undefined {
  return assetIndex.get(assetId);
}

export function assetForSpecimen(specimen: Specimen): AssetRecord {
  const asset = assetIndex.get(specimen.assetId);
  if (!asset) throw new Error(`Unknown asset: ${specimen.assetId}`);
  return asset;
}

export function getSource(sourceId: string): Source | undefined {
  return sourceIndex.get(sourceId);
}
