import { pathForRoute, ROUTES, type RouteId } from "../routes";
import { navigate } from "../lib/navigation";
import { useSlidingPill } from "../lib/use-sliding-pill";
import { IconMoon, IconSun } from "./Icons";

export function SiteHeader({
  route,
  theme,
  reduceMotion,
  onSelectTheme,
}: {
  route: RouteId;
  theme: "light" | "dark";
  reduceMotion: boolean;
  onSelectTheme: (theme: "light" | "dark") => void;
}) {
  const navIndex = Math.max(
    0,
    ROUTES.findIndex((entry) => entry.id === route),
  );
  const navPill = useSlidingPill<HTMLAnchorElement>(navIndex, reduceMotion);
  const themePill = useSlidingPill<HTMLButtonElement>(theme === "light" ? 0 : 1, reduceMotion);

  return (
    <header className="site-header">
      <div className="site-header__inner">
        <a
          className="brand"
          href={pathForRoute("explore")}
          onClick={(event) => {
            if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
            event.preventDefault();
            navigate("explore");
          }}
        >
          <span className="brand__mark" aria-hidden="true">
            <span />
            <span />
            <span />
          </span>
          <span className="brand__text">
            <strong>Cell Architecture</strong>
            <span>Studio</span>
          </span>
        </a>

        <nav className="site-nav" aria-label="Primary" ref={navPill.containerRef}>
          <span className="spring-pill" aria-hidden="true" ref={navPill.pillRef} />
          {ROUTES.map((entry, index) => (
            <a
              key={entry.id}
              ref={navPill.registerItem(index)}
              href={pathForRoute(entry.id)}
              className="site-nav__link"
              aria-current={route === entry.id ? "page" : undefined}
              title={entry.description}
              onClick={(event) => {
                if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
                event.preventDefault();
                navigate(entry.id);
              }}
            >
              {entry.label}
            </a>
          ))}
        </nav>

        <div
          className="theme-toggle"
          role="group"
          aria-label="Color theme"
          ref={themePill.containerRef}
        >
          <span className="spring-pill" aria-hidden="true" ref={themePill.pillRef} />
          <button
            ref={themePill.registerItem(0)}
            type="button"
            className="theme-toggle__btn"
            aria-label="Light mode"
            title="Light mode"
            aria-pressed={theme === "light"}
            onClick={() => onSelectTheme("light")}
          >
            <IconSun />
          </button>
          <button
            ref={themePill.registerItem(1)}
            type="button"
            className="theme-toggle__btn"
            aria-label="Dark mode"
            title="Dark mode"
            aria-pressed={theme === "dark"}
            onClick={() => onSelectTheme("dark")}
          >
            <IconMoon />
          </button>
        </div>
      </div>
    </header>
  );
}
