import {
  TRAIT_LABELS,
  assetForSpecimen,
  getAsset,
  getSource,
  getSpecimen,
  catalog as registry,
  type AssetRecord,
  type CompareTraitId,
  type Specimen,
} from "@cas/content-registry/catalog";
import { resolveAppPath } from "./lib/base-path";

export const REGISTRY = registry;
export const REGISTRY_SPECIMENS: Specimen[] = registry.specimens;
export const REGISTRY_SOURCES = registry.sources;
export const TRAIT_ORDER: CompareTraitId[] = [
  "nucleus",
  "cell-wall",
  "chloroplasts",
  "motility",
  "typical-size",
  "organisation",
];

export { TRAIT_LABELS, getSource };

export function specimenById(id: string): Specimen | undefined {
  return getSpecimen(id);
}

export function requireSpecimen(id: string): Specimen {
  const specimen = getSpecimen(id);
  if (!specimen) throw new Error(`Unknown specimen ${id}`);
  return specimen;
}

export function previewUrl(path: string): string {
  return resolveAppPath(path);
}

const resolvedAssets = new Map<string, AssetRecord>();

export function assetFor(specimen: Specimen): AssetRecord {
  const cached = resolvedAssets.get(specimen.id);
  if (cached) return cached;
  const asset = assetForSpecimen(specimen) ?? getAsset(specimen.assetId);
  if (!asset) throw new Error(`Specimen ${specimen.id} has no asset`);
  const resolved = { ...asset, uri: resolveAppPath(asset.uri) };
  resolvedAssets.set(specimen.id, resolved);
  return resolved;
}
