import { Component, type ErrorInfo, type ReactNode } from "react";

type Props = { children: ReactNode; fallback: ReactNode };
type State = { failed: boolean };

/** Keeps a failed viewer chunk or renderer from blanking the accessible page. */
export class ViewerBoundary extends Component<Props, State> {
  override state: State = { failed: false };

  static getDerivedStateFromError(): State {
    return { failed: true };
  }

  override componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error("Viewer boundary caught an error", error, info.componentStack);
  }

  override render(): ReactNode {
    if (this.state.failed) return this.props.fallback;
    return this.props.children;
  }
}

export function ViewerSkeleton({
  previewPath,
  name,
  detail,
}: {
  previewPath: string;
  name: string;
  detail?: string;
}) {
  return (
    <div className="viewer-skeleton" role="status" aria-live="polite">
      <img
        src={previewPath}
        alt={`${name} schematic preview while the 3D viewer loads`}
        width={640}
        height={640}
      />
      <div className="viewer-skeleton__label">
        <span className="spinner" aria-hidden="true" />
        <span>{detail ?? `Loading the 3D viewer for ${name}…`}</span>
      </div>
    </div>
  );
}

export function ViewerLoadFallback({
  previewPath,
  name,
  message,
}: {
  previewPath: string;
  name: string;
  message: string;
}) {
  return (
    <div className="viewer-skeleton viewer-skeleton--error" role="alert">
      <img src={previewPath} alt={`${name} schematic preview`} width={640} height={640} />
      <div className="viewer-skeleton__label">
        <strong>3D viewer unavailable</strong>
        <span>{message}</span>
        <button
          type="button"
          className="button button--primary"
          onClick={() => window.location.reload()}
        >
          Reload page
        </button>
      </div>
    </div>
  );
}
