import type {
  AssetCapabilities,
  MaterialSpec,
  PartSpec,
  RepeatSpec,
  Structure,
  TutorFact,
  Vec3,
} from "./schema";

/** Authoring helpers: fill schema defaults once so specimen files stay readable. */

export function mat(color: string, overrides: Partial<MaterialSpec> = {}): MaterialSpec {
  return {
    color,
    roughness: overrides.roughness ?? 0.55,
    metalness: overrides.metalness ?? 0.03,
    opacity: overrides.opacity ?? 1,
    clearcoat: overrides.clearcoat ?? 0,
    clearcoatRoughness: overrides.clearcoatRoughness ?? 0.25,
    ...(overrides.emissive !== undefined ? { emissive: overrides.emissive } : {}),
    emissiveIntensity: overrides.emissiveIntensity ?? 0,
    flatShading: overrides.flatShading ?? false,
  };
}

export type PartInput = {
  id: string;
  shape: PartSpec["shape"];
  position: Vec3;
  scale: Vec3;
  material: MaterialSpec;
  rotation?: Vec3;
  structureId?: string;
  cutawayHide?: boolean;
  outline?: boolean;
  segments?: number;
  mirrorZ?: boolean;
  repeat?: RepeatSpec;
};

export function part(input: PartInput): PartSpec {
  return {
    id: input.id,
    shape: input.shape,
    position: input.position,
    rotation: input.rotation ?? [0, 0, 0],
    scale: input.scale,
    material: input.material,
    ...(input.structureId !== undefined ? { structureId: input.structureId } : {}),
    cutawayHide: input.cutawayHide ?? false,
    outline: input.outline ?? false,
    segments: input.segments ?? 32,
    ...(input.mirrorZ !== undefined ? { mirrorZ: input.mirrorZ } : {}),
    ...(input.repeat !== undefined ? { repeat: input.repeat } : {}),
  };
}

function quaternionToEulerXYZ(qx: number, qy: number, qz: number, qw: number): Vec3 {
  const qLen = Math.hypot(qx, qy, qz, qw);
  const x = qx / qLen;
  const y = qy / qLen;
  const z = qz / qLen;
  const w = qw / qLen;

  const m11 = 1 - 2 * (y * y + z * z);
  const m12 = 2 * (x * y - z * w);
  const m13 = 2 * (x * z + y * w);
  const m22 = 1 - 2 * (x * x + z * z);
  const m23 = 2 * (y * z - x * w);
  const m32 = 2 * (y * z + x * w);
  const m33 = 1 - 2 * (x * x + y * y);

  const clamped = Math.max(-1, Math.min(1, m13));
  const ry = Math.asin(clamped);
  if (Math.abs(clamped) < 0.999999) {
    return [Math.atan2(-m23, m33), ry, Math.atan2(-m12, m11)];
  }
  return [Math.atan2(m32, m22), ry, 0];
}

/**
 * Returns Three.js intrinsic XYZ Euler angles that rotate local +Y onto the
 * given direction vector, keeping multi-part limbs and surface appendages
 * connected without importing Three.js into the content registry.
 */
export function alignYToVector(dir: Vec3): Vec3 {
  const len = Math.hypot(dir[0], dir[1], dir[2]);
  if (len < 1e-6) return [0, 0, 0];
  const dx = dir[0] / len;
  const dy = dir[1] / len;
  const dz = dir[2] / len;
  if (dy > 0.999999) return [0, 0, 0];
  if (dy < -0.999999) return [Math.PI, 0, 0];
  return quaternionToEulerXYZ(dz, 0, -dx, 1 + dy);
}

/**
 * Returns Three.js intrinsic XYZ Euler angles that rotate local +Z onto the
 * given direction vector (used for surface-flush rings and pores).
 */
export function alignZToVector(dir: Vec3): Vec3 {
  const len = Math.hypot(dir[0], dir[1], dir[2]);
  if (len < 1e-6) return [0, 0, 0];
  const dx = dir[0] / len;
  const dy = dir[1] / len;
  const dz = dir[2] / len;
  if (dz > 0.999999) return [0, 0, 0];
  if (dz < -0.999999) return [Math.PI, 0, 0];
  return quaternionToEulerXYZ(-dy, dx, 0, 1 + dz);
}

/** Positions, scales, and rotates a unit-Y part between two world endpoints. */
export function limbBetween(
  from: Vec3,
  to: Vec3,
  radius: number,
  lengthDivisor = 1,
): { position: Vec3; rotation: Vec3; scale: Vec3 } {
  const dx = to[0] - from[0];
  const dy = to[1] - from[1];
  const dz = to[2] - from[2];
  const length = Math.hypot(dx, dy, dz);
  return {
    position: [(from[0] + to[0]) / 2, (from[1] + to[1]) / 2, (from[2] + to[2]) / 2],
    rotation: alignYToVector([dx, dy, dz]),
    scale: [radius, Math.max(0.01, length / lengthDivisor), radius],
  };
}

export function rep(input: {
  count: number;
  pattern: RepeatSpec["pattern"];
  seed?: number;
  extent?: Vec3;
  radius?: number;
  turns?: number;
  axis?: RepeatSpec["axis"];
  jitter?: number;
  jitterRotation?: number;
}): RepeatSpec {
  return {
    count: input.count,
    pattern: input.pattern,
    seed: input.seed ?? 1,
    extent: input.extent ?? [0.5, 0.5, 0.5],
    radius: input.radius ?? 0.5,
    turns: input.turns ?? 2,
    axis: input.axis ?? "y",
    jitter: input.jitter ?? 0,
    jitterRotation: input.jitterRotation ?? 0,
  };
}

export function capabilities(options: { cutaway?: boolean } = {}): AssetCapabilities {
  return {
    mesh: true,
    focus: true,
    cutaway: options.cutaway ?? false,
    structureHighlight: "mesh-mapping",
    screenshot: true,
    glbExport: true,
  };
}

export type StructureInput = {
  id: string;
  name: string;
  shortName?: string;
  summary: string;
  function: string;
  facts: TutorFact[];
  /** Parent part IDs in the procedural spec. */
  meshNames: string[];
  note?: string;
  schematicNote?: string;
  confidence?: "high" | "medium" | "low";
};

export function structure(input: StructureInput): Structure {
  return {
    id: input.id,
    name: input.name,
    ...(input.shortName ? { shortName: input.shortName } : {}),
    summary: input.summary,
    function: input.function,
    facts: input.facts,
    mapping: {
      kind: "mesh-mapping",
      meshNames: input.meshNames,
      confidence: input.confidence ?? "high",
      evidence:
        "Each listed mesh is generated from this structure's authored procedural entry; the mapping is code-reviewed with the specimen definition.",
      note:
        input.note ??
        "Schematic teaching geometry. Positions, counts, and proportions are illustrative and are not measurements.",
    },
    ...(input.schematicNote ? { schematicNote: input.schematicNote } : {}),
  };
}

export function indexed(prefix: string, count: number): string[] {
  return Array.from({ length: count }, (_, idx) => `${prefix}${idx}`);
}

export function indexedPairs(prefixes: readonly string[], count: number): string[] {
  return Array.from({ length: count }, (_, idx) =>
    prefixes.map((prefix) => `${prefix}${idx}`),
  ).flat();
}

export function fact(
  specimenId: string,
  structureId: string,
  index: number,
  statement: string,
  sourceId: string,
  locator: string,
  highImpact = false,
): TutorFact {
  return {
    id: `${specimenId}.${structureId}.${index}`,
    statement,
    sourceId,
    locator,
    highImpact,
    secondReview: null,
  };
}

