import { z } from "zod";
import type { Registry } from "@cas/content-registry";

export type TutorContext = {
  question: string;
  specimenId?: string;
  structureId?: string;
};

export type TutorCitation = {
  sourceId: string;
  sourceTitle: string;
  locator: string;
  url: string;
  statement: string;
};

export type TutorAnswer =
  | { kind: "answer"; text: string; citations: TutorCitation[]; providerId: string }
  | {
      kind: "refusal";
      reason: "unsupported" | "disabled" | "error" | "timeout";
      message: string;
      providerId: string;
    };

export type TutorProvider = {
  id: string;
  mode: "static" | "remote";
  isAvailable: () => boolean;
  ask: (context: TutorContext, options?: { signal?: AbortSignal }) => Promise<TutorAnswer>;
};

const STOP_WORDS = new Set([
  "the",
  "a",
  "an",
  "and",
  "or",
  "of",
  "to",
  "in",
  "is",
  "are",
  "was",
  "were",
  "does",
  "do",
  "did",
  "what",
  "which",
  "how",
  "why",
  "where",
  "when",
  "this",
  "that",
  "these",
  "those",
  "for",
  "with",
  "about",
  "can",
  "could",
  "would",
  "should",
  "tell",
  "me",
  "cell",
  "cells",
]);

function tokenize(value: string): string[] {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .split(/\s+/)
    .map((token) => token.trim())
    .filter((token) => token.length > 2 && !STOP_WORDS.has(token));
}

/**
 * Offline study helper. It can only repeat authored, cited statements; there is
 * no language model, so an unsupported question must be refused rather than
 * answered from general knowledge.
 */
export function createStaticTutor(registry: Registry): TutorProvider {
  const entries = registry.specimens.flatMap((specimen) =>
    specimen.structures.flatMap((structure) =>
      structure.facts.map((fact) => {
        const source = registry.sources.find((candidate) => candidate.id === fact.sourceId);
        if (!source) throw new Error(`Tutor fact ${fact.id} cites missing source`);
        return { specimen, structure, fact, source };
      }),
    ),
  );

  return {
    id: "static-facts",
    mode: "static",
    isAvailable: () => true,
    ask: async (context) => {
      const question = context.question.trim().slice(0, 500);
      if (question.length < 3) {
        return {
          kind: "refusal",
          reason: "unsupported",
          providerId: "static-facts",
          message: "Ask a short question about a structure in this gallery.",
        };
      }
      const tokens = tokenize(question);
      if (tokens.length === 0) {
        return {
          kind: "refusal",
          reason: "unsupported",
          providerId: "static-facts",
          message:
            "I can only answer from the reviewed statements in this gallery. Try naming a structure or asking what it does.",
        };
      }

      const questionLower = question.toLowerCase();
      const scored = entries
        .map((entry) => {
          const nameTokens = tokenize(entry.structure.name);
          const nameMatch = nameTokens.some((token) => questionLower.includes(token));
          const statementTokens = new Set(tokenize(entry.fact.statement));
          const overlap = tokens.filter((token) => statementTokens.has(token)).length;
          const scopedSpecimen = context.specimenId
            ? entry.specimen.id === context.specimenId
            : false;
          const scopedStructure = context.structureId
            ? entry.structure.id === context.structureId
            : false;
          const score =
            overlap + (nameMatch ? 3 : 0) + (scopedStructure ? 4 : 0) + (scopedSpecimen ? 1 : 0);
          return { entry, score, nameMatch, overlap };
        })
        .filter((candidate) => candidate.score >= 3)
        .sort((a, b) => b.score - a.score || a.entry.fact.id.localeCompare(b.entry.fact.id));

      if (scored.length === 0) {
        return {
          kind: "refusal",
          reason: "unsupported",
          providerId: "static-facts",
          message:
            "That question is not covered by the reviewed facts in this gallery. I will not guess. Try a structure name from the list, such as “nucleus” or “cell wall”.",
        };
      }

      const best = scored[0]!;
      const related = scored
        .filter(
          (candidate) =>
            candidate.entry.structure.id === best.entry.structure.id &&
            candidate.entry.specimen.id === best.entry.specimen.id,
        )
        .slice(0, 2);
      const statements = [...new Set(related.map((candidate) => candidate.entry.fact.statement))];
      const citations = related.map((candidate) => ({
        sourceId: candidate.entry.source.id,
        sourceTitle: candidate.entry.source.title,
        locator: candidate.entry.fact.locator,
        url: candidate.entry.source.url,
        statement: candidate.entry.fact.statement,
      }));

      return {
        kind: "answer",
        providerId: "static-facts",
        text: `${best.entry.structure.name} (${best.entry.specimen.name}): ${statements.join(" ")}`,
        citations,
      };
    },
  };
}

export const RemoteTutorResponseSchema = z.object({
  answer: z.string().min(1).max(4000),
  citations: z
    .array(
      z.object({
        sourceId: z.string().min(2),
        locator: z.string().min(2),
        statement: z.string().min(2).optional(),
      }),
    )
    .max(8)
    .default([]),
});
export type RemoteTutorResponse = z.infer<typeof RemoteTutorResponseSchema>;

export type RemoteTutorConfig = {
  endpoint: string | null;
  enabled: boolean;
  consent: boolean;
  fetchImpl?: typeof fetch;
  timeoutMs?: number;
  /** Injected for tests; defaults to the registry sources. */
  registry?: Registry;
};

/**
 * Adapter for a trusted tutor backend. It is unavailable unless the user has
 * opted in, a reviewed HTTPS endpoint is configured, and the caller explicitly
 * enables it. No API key belongs in this client.
 */
export function createRemoteTutor(config: RemoteTutorConfig): TutorProvider {
  const endpoint = config.endpoint?.trim() ?? "";
  const available = config.enabled && config.consent && endpoint.startsWith("https://");

  return {
    id: "remote",
    mode: "remote",
    isAvailable: () => available,
    ask: async (context, options = {}) => {
      const providerId = "remote";
      if (!available) {
        return {
          kind: "refusal",
          reason: "disabled",
          providerId,
          message:
            "Live tutoring is off. It stays unavailable until you opt in and a reviewed HTTPS provider is configured.",
        };
      }

      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), config.timeoutMs ?? 12_000);
      const onAbort = () => controller.abort();
      options.signal?.addEventListener("abort", onAbort, { once: true });
      const fetchImpl = config.fetchImpl ?? fetch;

      try {
        const response = await fetchImpl(endpoint, {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          credentials: "omit",
          signal: controller.signal,
          body: JSON.stringify({
            question: context.question.slice(0, 500),
            specimenId: context.specimenId ?? null,
            structureId: context.structureId ?? null,
          }),
        });
        if (!response.ok) {
          return {
            kind: "refusal",
            reason: "error",
            providerId,
            message: `The tutor service returned HTTP ${response.status}. Nothing was saved.`,
          };
        }
        const parsed = RemoteTutorResponseSchema.safeParse(await response.json());
        if (!parsed.success) {
          return {
            kind: "refusal",
            reason: "error",
            providerId,
            message: "The tutor response did not match the reviewed response format.",
          };
        }
        const citations = parsed.data.citations.flatMap((citation) => {
          const source = config.registry?.sources.find(
            (candidate) => candidate.id === citation.sourceId,
          );
          if (!source) return [];
          return [
            {
              sourceId: source.id,
              sourceTitle: source.title,
              locator: citation.locator,
              url: source.url,
              statement: citation.statement ?? "",
            },
          ];
        });
        return {
          kind: "answer",
          providerId,
          text: parsed.data.answer,
          citations,
        };
      } catch (cause) {
        const aborted =
          (cause instanceof DOMException && cause.name === "AbortError") ||
          (cause instanceof Error && cause.name === "AbortError");
        return {
          kind: "refusal",
          reason: aborted ? "timeout" : "error",
          providerId,
          message: aborted
            ? "The tutor request timed out. The offline study helper still works."
            : "The tutor service could not be reached. The offline study helper still works.",
        };
      } finally {
        clearTimeout(timeout);
        options.signal?.removeEventListener("abort", onAbort);
      }
    },
  };
}
