import { appStore, type LabSimulationId } from "../state/app-store";
import { pathForRoute, type RouteId } from "../routes";

export function navigate(route: RouteId): void {
  const path = pathForRoute(route);
  if (typeof window !== "undefined") {
    if (window.location.pathname !== path) {
      window.history.pushState({ route }, "", path);
    }
    window.scrollTo({ top: 0, behavior: "auto" });
  }
  appStore.getState().setRoute(route);
}

export function navigateToLab(simulation: LabSimulationId): void {
  appStore.getState().setLabSimulation(simulation);
  navigate("lab");
}

export function navigateToStructure(specimenId: string, structureId: string): void {
  appStore.getState().selectSpecimen(specimenId);
  appStore.getState().selectStructure(structureId);
  appStore.getState().markStructureViewed(specimenId, structureId);
  navigate("explore");
}

export function nextTabIndex(key: string, index: number, length: number): number | null {
  if (length <= 0) return null;
  switch (key) {
    case "ArrowRight":
      return (index + 1) % length;
    case "ArrowLeft":
      return (index - 1 + length) % length;
    case "Home":
      return 0;
    case "End":
      return length - 1;
    default:
      return null;
  }
}
