import { lazy, Suspense, useEffect, useRef, type CSSProperties } from "react";
import { appStore } from "./state/app-store";
import { useVanillaStore } from "./lib/use-vanilla-store";
import { isKnownPath, pathForRoute, routeFromPath, routeLabel } from "./routes";
import { navigate } from "./lib/navigation";
import { SiteHeader } from "./components/SiteHeader";
import { ExplorePage } from "./pages/ExplorePage";
import {
  effectiveReducedMotion,
  effectiveTheme,
  useSystemColorScheme,
  useSystemReducedMotion,
} from "./lib/media";
import { requireSpecimen } from "./content";

const ComparePage = lazy(() =>
  import("./pages/ComparePage").then((m) => ({ default: m.ComparePage })),
);
const LearnPage = lazy(() => import("./pages/LearnPage").then((m) => ({ default: m.LearnPage })));
const LabPage = lazy(() => import("./pages/LabPage").then((m) => ({ default: m.LabPage })));
const AboutPage = lazy(() => import("./pages/AboutPage").then((m) => ({ default: m.AboutPage })));

export function App() {
  const route = useVanillaStore(appStore, (s) => s.route);
  const specimenId = useVanillaStore(appStore, (s) => s.specimenId);
  const notice = useVanillaStore(appStore, (s) => s.notice);
  const themePref = useVanillaStore(appStore, (s) => s.settings.theme);
  const reduceMotionPref = useVanillaStore(appStore, (s) => s.settings.reduceMotion);
  const systemReduced = useSystemReducedMotion();
  const systemScheme = useSystemColorScheme();
  const reduceMotion = effectiveReducedMotion(reduceMotionPref, systemReduced);
  const resolvedTheme = effectiveTheme(themePref, systemScheme);
  const specimen = requireSpecimen(specimenId);
  const mainRef = useRef<HTMLElement>(null);
  const previousRoute = useRef(route);

  useEffect(() => {
    document.documentElement.dataset.theme = resolvedTheme;
    document.documentElement.style.colorScheme = resolvedTheme;
    document
      .querySelector('meta[name="theme-color"]')
      ?.setAttribute("content", resolvedTheme === "light" ? "#f2f2f7" : "#09090b");
  }, [resolvedTheme]);

  useEffect(() => {
    const onPopState = () => appStore.getState().setRoute(routeFromPath(window.location.pathname));
    window.addEventListener("popstate", onPopState);

    if (!isKnownPath(window.location.pathname)) {
      window.history.replaceState({ route: "explore" }, "", pathForRoute("explore"));
      appStore.getState().setRoute("explore");
    }
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  useEffect(() => {
    const title =
      route === "explore"
        ? `${specimen.name} · Cell Architecture Studio`
        : `${routeLabel(route)} · Cell Architecture Studio`;
    document.title = title;
  }, [route, specimen.name]);

  useEffect(() => {
    if (previousRoute.current !== route) {
      previousRoute.current = route;
      mainRef.current?.focus({ preventScroll: true });
    }
  }, [route]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => appStore.getState().notify(""), 10_000);
    return () => clearTimeout(timer);
  }, [notice]);

  return (
    <div
      className="app-shell"
      style={{ "--accent": specimen.accent } as CSSProperties}
      data-theme={resolvedTheme}
      data-reduce-motion={reduceMotion ? "true" : "false"}
    >
      <a className="skip-link" href="#main">
        Skip to main content
      </a>
      <SiteHeader
        route={route}
        theme={resolvedTheme}
        reduceMotion={reduceMotion}
        onSelectTheme={(theme) => appStore.getState().setTheme(theme)}
      />
      <div className="draft-banner" role="region" aria-label="Draft content notice">
        <div className="draft-banner__inner">
          <span className="draft-banner__dot" aria-hidden="true" />
          <p>
            <strong>Draft teaching content.</strong> Biology review is in progress; high-impact
            claims need a second reviewer before release. Not medical advice.
          </p>
        </div>
      </div>

      <div
        className="notice-region"
        role="region"
        aria-label="Application messages"
        aria-live="polite"
        aria-atomic="true"
      >
        {notice && (
          <p className="notice">
            {notice}
            <button
              type="button"
              className="notice__dismiss"
              aria-label="Dismiss message"
              onClick={() => appStore.getState().notify("")}
            >
              ×
            </button>
          </p>
        )}
      </div>

      <main id="main" ref={mainRef} tabIndex={-1} className="site-main">
        <Suspense
          fallback={
            <div className="page" role="status" aria-live="polite">
              <p className="muted">Loading view…</p>
            </div>
          }
        >
          {route === "explore" && <ExplorePage />}
          {route === "compare" && <ComparePage />}
          {route === "learn" && <LearnPage />}
          {route === "lab" && <LabPage />}
          {route === "about" && <AboutPage />}
        </Suspense>
      </main>

      <footer className="site-footer">
        <div>
          <p>
            <strong>Cell Architecture Studio</strong> · local-first teaching models.
          </p>
          <p className="muted small">
            Schematic content licensed{" "}
            <a
              href="https://creativecommons.org/licenses/by/4.0/"
              target="_blank"
              rel="noreferrer noopener"
            >
              CC BY 4.0
            </a>
            . Sources: OpenStax, Britannica, NCBI Bookshelf.
          </p>
        </div>
        <nav aria-label="Footer">
          <button type="button" className="link-button" onClick={() => navigate("about")}>
            Provenance &amp; privacy
          </button>
          <button type="button" className="link-button" onClick={() => navigate("learn")}>
            Study mode
          </button>
          <button type="button" className="link-button" onClick={() => navigate("lab")}>
            Bilayer lab
          </button>
        </nav>
      </footer>
    </div>
  );
}
