import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { createSpringValue, SPRING_SNAPPY } from "./spring";

/**
 * Drives an Apple-style sliding indicator pill behind active tabs or segmented
 * controls using two independent spring channels (X and width) directly in DOM
 * transforms with zero per-frame React re-renders.
 */
export function useSlidingPill<T extends HTMLElement = HTMLButtonElement>(
  activeIndex: number,
  reduceMotion: boolean,
) {
  const containerRef = useRef<HTMLDivElement>(null);
  const pillRef = useRef<HTMLSpanElement>(null);
  const itemsRef = useRef<Array<T | null>>([]);
  const initializedRef = useRef(false);
  const [springs] = useState(() => ({
    x: createSpringValue(0),
    w: createSpringValue(0),
  }));

  const registerItem = useCallback(
    (index: number) => (node: T | null) => {
      itemsRef.current[index] = node;
    },
    [],
  );

  const applyPillStyle = useCallback(() => {
    const pill = pillRef.current;
    if (!pill) return;
    const x = springs.x.getValue();
    const w = springs.w.getValue();
    pill.style.transform = `translate3d(${x.toFixed(2)}px, 0, 0)`;
    pill.style.width = `${Math.max(0, w).toFixed(2)}px`;
  }, [springs]);

  useEffect(() => {
    const unsubX = springs.x.subscribe(applyPillStyle);
    const unsubW = springs.w.subscribe(applyPillStyle);
    return () => {
      unsubX();
      unsubW();
      springs.x.stop();
      springs.w.stop();
    };
  }, [applyPillStyle, springs]);

  const measureAndSync = useCallback(
    (snap: boolean) => {
      const container = containerRef.current;
      const pill = pillRef.current;
      const targetEl = activeIndex >= 0 ? itemsRef.current[activeIndex] : null;
      if (!container || !pill || !targetEl) {
        if (container) container.dataset.pillReady = "false";
        return;
      }

      const width = targetEl.offsetWidth;
      const left = targetEl.offsetLeft;
      if (width <= 0) {
        container.dataset.pillReady = "false";
        return;
      }

      container.dataset.pillReady = "true";
      pill.style.opacity = "1";

      if (snap || reduceMotion || !initializedRef.current) {
        initializedRef.current = true;
        springs.x.setImmediate(left);
        springs.w.setImmediate(width);
        applyPillStyle();
      } else {
        springs.x.setTarget(left, { config: SPRING_SNAPPY, precision: 0.1 });
        springs.w.setTarget(width, { config: SPRING_SNAPPY, precision: 0.1 });
      }
    },
    [activeIndex, applyPillStyle, reduceMotion, springs],
  );

  useLayoutEffect(() => {
    measureAndSync(false);
  }, [measureAndSync]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => measureAndSync(true));
    observer.observe(container);
    return () => observer.disconnect();
  }, [measureAndSync]);

  return { containerRef, pillRef, registerItem };
}
