import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import {
  PersistenceError,
  requestPersistentStorage,
  resolvePersistenceAdapter,
  type PersistenceAdapter,
} from "@cas/persistence";
import { appStore } from "../state/app-store";

export type PersistenceStatus = "loading" | "ready" | "memory" | "error";

type PersistenceContextValue = {
  status: PersistenceStatus;
  adapterKind: PersistenceAdapter["kind"] | null;
  exportData: () => Promise<void>;
  deleteData: () => Promise<void>;
  requestPersistence: () => Promise<void>;
};

const PersistenceContext = createContext<PersistenceContextValue | null>(null);

function downloadJson(filename: string, data: unknown): void {
  const blob = new Blob([`${JSON.stringify(data, null, 2)}\n`], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.rel = "noopener";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function PersistenceProvider({ children }: { children: ReactNode }) {
  const [adapter] = useState<PersistenceAdapter>(() => resolvePersistenceAdapter());
  const [status, setStatus] = useState<PersistenceStatus>("loading");
  const statusRef = useRef<PersistenceStatus>("loading");
  const saveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cancelPendingSave = useCallback(() => {
    if (saveTimerRef.current) {
      clearTimeout(saveTimerRef.current);
      saveTimerRef.current = null;
    }
  }, []);

  const persistCurrentState = useCallback(async () => {
    cancelPendingSave();
    if (statusRef.current !== "ready" && statusRef.current !== "memory") return;
    const state = appStore.getState();
    await adapter.saveProfile(state.profile);
    await adapter.saveSettings(state.settings);
  }, [adapter, cancelPendingSave]);

  useEffect(() => {
    statusRef.current = status;
  }, [status]);

  useEffect(() => {
    let cancelled = false;
    adapter
      .load()
      .then((loaded) => {
        if (cancelled) return;
        appStore.getState().hydrate({
          profile: loaded.profile,
          settings: loaded.settings,
          persistenceKind: loaded.kind,
        });
        setStatus(loaded.kind === "indexeddb" ? "ready" : "memory");
        if (loaded.recovered) {
          appStore
            .getState()
            .notify(
              "Stored progress could not be read and was replaced with a fresh local profile.",
            );
        } else if (loaded.kind === "memory") {
          appStore
            .getState()
            .notify("Storage is unavailable, so progress is kept only for this tab.");
        }
      })
      .catch((cause: unknown) => {
        if (cancelled) return;
        const message =
          cause instanceof PersistenceError
            ? cause.message
            : "Local progress storage could not be opened. This session will not be saved.";
        appStore.getState().hydrate({
          profile: appStore.getState().profile,
          settings: appStore.getState().settings,
          persistenceKind: "error",
        });
        appStore.getState().notify(message);
        setStatus("error");
      });
    return () => {
      cancelled = true;
    };
  }, [adapter]);

  // Subscribe outside React so persistence runs only when the persisted slices
  // change, not on viewer focus or route changes.
  useEffect(() => {
    const unsubscribe = appStore.subscribe((state, previous) => {
      if (statusRef.current !== "ready" && statusRef.current !== "memory") return;
      if (state.profile === previous.profile && state.settings === previous.settings) return;
      cancelPendingSave();
      saveTimerRef.current = setTimeout(() => {
        saveTimerRef.current = null;
        void adapter
          .saveProfile(state.profile)
          .then(() => adapter.saveSettings(state.settings))
          .catch((cause: unknown) => {
            appStore
              .getState()
              .notify(
                cause instanceof PersistenceError && cause.code === "quota"
                  ? "Browser storage is full. Export your data or reset progress."
                  : "Progress could not be saved locally. The current session still works.",
              );
          });
      }, 350);
    });
    return () => {
      unsubscribe();
      cancelPendingSave();
    };
  }, [adapter, cancelPendingSave]);

  // Flush a pending debounce when the tab is hidden or closed.
  useEffect(() => {
    const flush = () => {
      void persistCurrentState().catch(() => {
        /* Best effort on unload; the next session reports any stored recovery. */
      });
    };
    const onVisibility = () => {
      if (document.visibilityState === "hidden") flush();
    };
    window.addEventListener("pagehide", flush);
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      window.removeEventListener("pagehide", flush);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [persistCurrentState]);

  const exportData = useCallback(async () => {
    const state = appStore.getState();
    try {
      await persistCurrentState();
      const bundle = await adapter.exportAll();
      downloadJson(`cell-architecture-progress-${bundle.exportedAt.slice(0, 10)}.json`, bundle);
      appStore
        .getState()
        .notify("Progress exported. The file contains no tutor prompts or secrets.");
    } catch {
      downloadJson(`cell-architecture-progress-${new Date().toISOString().slice(0, 10)}.json`, {
        app: "cell-architecture-studio",
        exportVersion: 2,
        exportedAt: new Date().toISOString(),
        profile: state.profile,
        settings: state.settings,
      });
      appStore
        .getState()
        .notify("Storage was unavailable; exported the in-memory profile for this session.");
    }
  }, [adapter, persistCurrentState]);

  const deleteData = useCallback(async () => {
    try {
      cancelPendingSave();
      await adapter.deleteAll();
      const loaded = await adapter.load();
      appStore.getState().hydrate({
        profile: loaded.profile,
        settings: loaded.settings,
        persistenceKind: statusRef.current === "error" ? "error" : loaded.kind,
      });
      cancelPendingSave();
      appStore.getState().notify("Local progress and settings were deleted from this browser.");
    } catch {
      appStore
        .getState()
        .notify("Local data could not be deleted. Close other tabs and try again.");
    }
  }, [adapter, cancelPendingSave]);

  const requestPersistence = useCallback(async () => {
    const granted = await requestPersistentStorage();
    appStore
      .getState()
      .notify(
        granted
          ? "The browser granted persistent storage for this site."
          : "The browser did not grant persistent storage. Progress still saves normally when space allows.",
      );
  }, []);

  return (
    <PersistenceContext.Provider
      value={{
        status,
        adapterKind: status === "loading" ? null : adapter.kind,
        exportData,
        deleteData,
        requestPersistence,
      }}
    >
      {children}
    </PersistenceContext.Provider>
  );
}

export function usePersistence(): PersistenceContextValue {
  const value = useContext(PersistenceContext);
  if (!value) throw new Error("usePersistence must be used inside PersistenceProvider");
  return value;
}
